import itertools
import json

def solve():
    houses = [1, 2, 3, 4, 5]
    Names = ["Eric", "Peter", "Arnold", "Alice", "Bob"]
    Mothers = ["Kailyn", "Janelle", "Aniya", "Penny", "Holly"]
    Heights = ["average", "very short", "short", "very tall", "tall"]

    solutions = []

    for names_perm in itertools.permutations(Names):
        # Constraint 4: Peter is not in the second house.
        if names_perm[1] == "Peter":
            continue
        # Constraint 8: Eric is not in the fifth house.
        if names_perm[4] == "Eric":
            continue

        idx_name = {names_perm[i]: i for i in range(5)}

        for mothers_perm in itertools.permutations(Mothers):
            # Constraint 3: The person whose mother's name is Janelle is Bob.
            if mothers_perm[idx_name["Bob"]] != "Janelle":
                continue
            # Constraint 10: Eric is The person whose mother's name is Kailyn.
            if mothers_perm[idx_name["Eric"]] != "Kailyn":
                continue
            # Constraint 1: Alice is The person whose mother's name is Aniya.
            if mothers_perm[idx_name["Alice"]] != "Aniya":
                continue

            # From clues 6 and 9, and uniqueness of mothers, deduce:
            # Arnold's mother must be Penny and Peter's mother must be Holly.
            if mothers_perm[idx_name["Arnold"]] != "Penny":
                continue
            if mothers_perm[idx_name["Peter"]] != "Holly":
                continue

            idx_mother = {mothers_perm[i]: i for i in range(5)}

            for heights_perm in itertools.permutations(Heights):
                # Constraint 11: The person who is very short is in the fifth house.
                if heights_perm[4] != "very short":
                    continue
                # Constraint 6: The person who is very tall is Arnold.
                if heights_perm[idx_name["Arnold"]] != "very tall":
                    continue
                # Constraint 5: The person who is short is directly left of Arnold.
                idx_short = heights_perm.index("short")
                if idx_short + 1 != idx_name["Arnold"]:
                    continue
                # Constraint 7: Bob is directly left of the person who has an average height.
                if idx_name["Bob"] + 1 != heights_perm.index("average"):
                    continue
                # Constraint 2: The person who has an average height is somewhere to the left of the person whose mother's name is Penny.
                if heights_perm.index("average") >= idx_mother["Penny"]:
                    continue
                # Constraint 9: The person who is very tall is somewhere to the right of the person whose mother's name is Holly.
                if heights_perm.index("very tall") <= idx_mother["Holly"]:
                    continue

                # All constraints satisfied; record solution
                row_solution = []
                for i in range(5):
                    row_solution.append([str(i + 1), names_perm[i], mothers_perm[i], heights_perm[i]])
                solutions.append(row_solution)

    # Prepare output
    if not solutions:
        raise ValueError("No solution found")
    # If multiple solutions exist, we'll output the first one found
    result = {
        "solution": {
            "header": ["House", "Name", "Mother", "Height"],
            "rows": solutions[0]
        }
    }
    print(json.dumps(result))

if __name__ == "__main__":
    solve()
